local PlayerSignDialog = Class("PlayerSignDialog")

function PlayerSignDialog:__init()
    self.signRewards = nil
    self.needCheck   = false
    self.co = nil 
end

function PlayerSignDialog:__delete()
    self.signRewards = nil
    self.needCheck   = false
end

function PlayerSignDialog:Awake()
    -- CfUtils.FillText(self.DayText, '')
end

function PlayerSignDialog:Refresh()
    self:RefreshCurrencyBarInfo()
    self:UpdateRewardNode()
    self:UpdateDayCellNode()
    self:UpdatePrograss()
end

function PlayerSignDialog:RefreshCurrencyBarInfo()
    GameUtils.UpdateNavBarShowState(true, false)
end

function PlayerSignDialog:UpdateRewardNode()
    local playerDojo = PlayerComponent.playerDojo
    local dailySignIn = playerDojo.dailySignIn
    local treasureRewards = dailySignIn.treasureRewards
    for i = 1 , #treasureRewards do
        self:UpdateOneRewardNode(i)
    end
    PlayerComponent:CheckPlayerSignInBox()
end

function PlayerSignDialog:UpdatePrograss(isUpdateRewards)
    local playerDojo = PlayerComponent.playerDojo
    local dailySignIn = playerDojo.dailySignIn
    local treasureRewards = dailySignIn.treasureRewards
    local treasureDays = checkInt(dailySignIn.treasureDays) 
    local countDay =  checkInt(treasureRewards[#treasureRewards].times)
    treasureDays = treasureDays >= countDay and countDay or treasureDays
    dailySignIn.treasureDays = treasureDays
    self.Slider.value = treasureDays / countDay
    if isUpdateRewards then
        if self.co then
            cs_coroutine.stop(self.co)
            self.co = nil
        end
        self.co = cs_coroutine.start(function ()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
            self.TxtNumCount.text = string.format("<size=58><color=#FFFFFF>%s</color></size>/%s" , treasureDays ,countDay )
            kTool.SetActive(self.UIFX_Progress ,true)
            for k, v in pairs(treasureRewards) do
                if checkInt(v.times)  == treasureDays  then
                    self:UpdateOneRewardNode(k)
                    break
                end
            end
        end)  
    else 
        self.TxtNumCount.text = string.format("<size=58><color=#FFFFFF>%s</color></size>/%s" , treasureDays ,countDay )   
    end
end



function PlayerSignDialog:UpdateShowTextGet()
    kTool.SetActive(self.TextGetTips.gameObject , true)
end
function PlayerSignDialog:UpdateOneRewardNode(index)
    local i = index 
    local playerDojo = PlayerComponent.playerDojo
    local dailySignIn = playerDojo.dailySignIn
    local treasureDays = checkInt(dailySignIn.treasureDays)
    local treasureDrawIds = dailySignIn.treasureDrawIds
    local RewardNode = self.RewardNode.transform:Find("RewardNode" .. i)
    local treasureRewards = dailySignIn.treasureRewards
    if isNotNull(RewardNode) then
        local oneTreasureRewards = treasureRewards[i] 
        local isHaveDraw = false 
        local times = checkInt(oneTreasureRewards.times)
        local TxtNumCount = RewardNode.transform:Find("TxtNumCount")
        CfUtils.FillText(TxtNumCount , times)
        for k, v in pairs(treasureDrawIds) do
            if checkInt(v) == checkInt(oneTreasureRewards.id) then
                isHaveDraw = true 
                break
            end
        end
        local isCanDraw  = false 
        if isHaveDraw then
           local GetNode = RewardNode:Find("GetNode") 
           kTool.SetActive(GetNode , true)
           local FX_glow2 =  RewardNode:Find("FX_glow2")
           if isNotNull(FX_glow2) then
                kTool.SetActive(FX_glow2.gameObject , false)
           end
           CfUtils.StopAnimation(RewardNode.gameObject)    
        else
            if checkInt(treasureDays) >= times then
                isCanDraw = true 
                CfUtils.PlayAnimation(RewardNode.gameObject,"DailyCheck_RewardNode_Complete")    
            end   
        end

        local BtnIocn = RewardNode.transform:Find("BtnIocn")
        SetButtonAction(BtnIocn , function ()
            if isCanDraw then
                GameUtils.Request(Interfaces.AccumulateSignInDraw, { boxId = oneTreasureRewards.id}, function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        local data = response.data 
                        GoodsUtils.DrawRewards(data.rewards , true)
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = data.rewards , cb = function()
                                        treasureDrawIds[#treasureDrawIds+1] = oneTreasureRewards.id
                                        local GetNode = RewardNode:Find("GetNode") 
                                        kTool.SetActive(GetNode,true)
                                        CfUtils.StopAnimation(RewardNode.gameObject)
                                        isCanDraw = false
                                        isHaveDraw = true
                                        if self:IsAllDrawRewards() then
                                            self:RefreshHome()
                                        else         
                                            self:UpdateRewardNode()
                                        end
                                    end}
                                }
                        )
                    end
                end)
            else 
                --刷新奖励
                GameUtils.ShowCommonTipsBoardRewardPreview(RewardNode, oneTreasureRewards.rewards, localize('奖励预览:'), false)
            end
        end)
    end
end

function PlayerSignDialog:IsAllDrawRewards()
    local playerDojo = PlayerComponent.playerDojo
    local dailySignIn = playerDojo.dailySignIn
    local treasureDays = checkInt(dailySignIn.treasureDays)
    local treasureDrawIds = dailySignIn.treasureDrawIds
    local treasureRewards = dailySignIn.treasureRewards
    local isAllDrawRewards = false
    for k, v in pairs(treasureRewards) do
        local isDraw = false 
        for kk, vv in pairs(treasureDrawIds) do
            if checkInt(v.id) == checkInt(vv)then
                isDraw  = true 
                break 
            end
        end
        if not isDraw then
            break
        end
    end
    return isAllDrawRewards
end

function PlayerSignDialog:UpdateDayCellNode()
    local playerDojo = PlayerComponent.playerDojo
    local dailySignIn = playerDojo.dailySignIn
    local signInRewards = dailySignIn.signInRewards 
    
    for i = 1, #signInRewards do
        self:UpdateDayCellNodeByIndex(i)
    end
end

function PlayerSignDialog:UpdateDayCellNodeByIndex(index)
    local playerDojo = PlayerComponent.playerDojo
    local dailySignIn = playerDojo.dailySignIn
    local signInRewards = dailySignIn.signInRewards 
    local transform = self.Content.transform
    local DayCell =  transform:Find("DayCell0" .. index )
    if isNotNull(DayCell) then
        ---@type SignCellNode
        local signEnv = CfUtils.GetLuaScr(DayCell, UISignNodeLuaPath)
        signEnv:FreshUI(signInRewards[index] , index , self)
    end
end

function PlayerSignDialog:RefreshHome()
    GameUtils.Request(Interfaces.SignInHome, {}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data 
            local playerDojo = PlayerComponent.playerDojo
            playerDojo.dailySignIn = data.dailySignIn
            self:Refresh()
        end
    end)
end
function PlayerSignDialog:OnDestroy()
    if self.co then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return PlayerSignDialog